const MANIFEST_DESTINATIONS: ReadonlySet<string> = new Set([
  "platform:destination@3", "platform:destination@4", "platform:destination@5",
  "platform:destination@6", "platform:destination@13", "platform:destination@14", "platform:destination@15", "platform:destination@16", "platform:destination@18", "platform:destination@19", "platform:destination@20",
]);

export const AGENT_KEY_MEMBERSHIPS = ["platform:membership@2", "platform:membership@4", "platform:membership@5", ...INVITATION_KEY_MEMBERSHIPS] as const;
export type AgentKeyMembership = (typeof AGENT_KEY_MEMBERSHIPS)[number];
export const isAgentKeyMembership = (value: unknown): value is AgentKeyMembership => typeof value === "string" && (AGENT_KEY_MEMBERSHIPS as readonly string[]).includes(value);

export const CHECKER_KEY_MEMBERSHIP = "platform:membership@8";
export const CHECKER_KEY_MEMBERSHIPS = [CHECKER_KEY_MEMBERSHIP, "platform:membership@12"] as const;
export type CheckerKeyMembership = typeof CHECKER_KEY_MEMBERSHIPS[number];
export const isCheckerKeyMembership = (value: unknown): value is CheckerKeyMembership => typeof value === "string" && (CHECKER_KEY_MEMBERSHIPS as readonly string[]).includes(value);

const LEGACY = ["platform:membership@1", "platform:membership@2", "platform:membership@4", "platform:membership@5"] as const;
/** Exact person-invitation pins with an implemented redemption encoding.
 * Callers must also have the native definition's join path. */
export const INVITATION_MEMBERSHIPS = [...LEGACY, ...INVITATION_KEY_MEMBERSHIPS] as const;
export type InvitationMembership = (typeof INVITATION_MEMBERSHIPS)[number];
export const isInvitationMembership = (value: unknown): value is InvitationMembership =>
  (INVITATION_MEMBERSHIPS as readonly unknown[]).includes(value);

const bindingFounder = plan.definition === "platform:register@25" && intent.fields["policy"] === "keys"
  && intent.fields["host"] === "none" && intent.fields["namespace"] === ""
  && Array.isArray(intent.fields["founders"]) && intent.fields["founders"].includes(key);

if (selected !== undefined && selected !== ARCHIVE_DEVICE_APPLICATION_COHORT.register) {
  return stopCommand(usage("--register-policy open requires a cohort with an open register policy; this run signed and sent nothing."));
}
return ARCHIVE_DEVICE_APPLICATION_COHORT.register;

const fixedLifetime = summary.definition === FAILED_CLAIM_COHORT.destination;
if (fixedLifetime && hours !== 1) return usage("This room issues one-hour read tokens; --hours must be 1.");
const tokenFields = fixedLifetime ? {} : { hours };

if (!birth || !("creator" in birth.to) || birth.to.definition !== "platform:inbox@1" || !sameOptional(birth.to.creator, membership)) return null;
const scope = scopeIdOf(birth.to), I = handle(reads, scope);
const summaryRead = await I.summary();
if (!summaryRead.ok && (summaryRead.reason === "not-found" || summaryRead.reason === "forbidden")) return { pending: scope };
if (!summaryRead.ok || !summaryRead.complete || summaryRead.next !== undefined || summaryRead.value.definition !== "platform:inbox@1" || summaryRead.value.scope.kind !== "inbox" || summaryRead.value.scope.scope !== scope) return null;

if (!held || held.pinned === UNPUBLISHED_COHORT.destination) {
  const { summary, at } = await this.#summary(scope, membership);
  const branches = summary.items.filter(item => item.type === "branch");
  const branch = branches.length === 1 ? branches[0]! : null;
  if (at.complete && summary.status === "active" && summary.scope.kind === "destination" && summary.scope.scope === scope
    && summary.definition === UNPUBLISHED_COHORT.destination && branch?.state === "unpublished"

async #applicationRoom(): Promise<{ directory: ScopeRef; membership: ScopeRef; rules: ScopeRef; destination: ScopeRef; cohort: typeof SEPARATE_RECOVERY_COHORT | typeof TRUSTED_APPLICATION_COHORT | typeof DECLARED_APPLICATION_COHORT | typeof DEVICE_APPLICATION_COHORT | typeof ARCHIVE_APPLICATION_COHORT | typeof ARCHIVE_DECLARED_APPLICATION_COHORT | typeof ARCHIVE_DEVICE_APPLICATION_COHORT | typeof ARCHIVE_DEVICE_PUBLICATION_COHORT | typeof UNPUBLISHED_COHORT | typeof REPOSITORY_BINDING_COHORT | typeof OWN_AGENT_COHORT | typeof FAILED_CLAIM_COHORT | typeof COMMONS_COHORT }> {

  const config = await this.#port.config.read(), repository = config.repository;
  if (!repository || config.service !== this.#service) return stopCall({ error: "target", what: "configure a trusted-application room before installing" });
  const { summary: directory } = await this.#summary(repository.directory.scope, repository.membership);
  const row = directory.items.find(item => item.type === "repository" && item.state === "open"), rules = row?.refs["rules"], destination = row?.refs["destination"];
  const cohort = [FAILED_CLAIM_COHORT, SEPARATE_RECOVERY_COHORT, TRUSTED_APPLICATION_COHORT, DECLARED_APPLICATION_COHORT, DEVICE_APPLICATION_COHORT, ARCHIVE_APPLICATION_COHORT, ARCHIVE_DECLARED_APPLICATION_COHORT, ARCHIVE_DEVICE_APPLICATION_COHORT, ARCHIVE_DEVICE_PUBLICATION_COHORT, UNPUBLISHED_COHORT, REPOSITORY_BINDING_COHORT, OWN_AGENT_COHORT, COMMONS_COHORT].find(cohort => directory.definition === cohort.directory);

  if (!cohort || directory.status !== "active" || canonicalize(directory.scope) !== canonicalize(repository.directory)
    || !row || canonicalize(row.refs["membership"]) !== canonicalize(repository.membership)
    || !isScopeRef(rules) || rules.kind !== "rules" || rules.scope !== repository.rules
    || !isScopeRef(destination) || destination.kind !== "destination" || destination.scope !== repository.destination) return stopCall({ error: "target", what: "the configured room does not match its exact generic native siblings" });
  const { summary } = await this.#summary(rules.scope, repository.membership);
  if (summary.status !== "active" || summary.definition !== cohort.rules || canonicalize(summary.scope) !== canonicalize(rules)) return stopCall({ error: "target", what: "the actual Rules sibling does not support native application installation" });
  if (cohort.directory === COMMONS_COHORT.directory) {
    const { summary: membership } = await this.#summary(repository.membership.scope, repository.membership);
    if (membership.status !== "active" || membership.definition !== COMMONS_COHORT.membership || canonicalize(membership.scope) !== canonicalize(repository.membership)) return stopCall({ error: "target", what: "the Commons room does not hold its exact Membership sibling" });
  }
